def stable_matching(proposers, receivers):
    # Track next proposal index for each proposer
    next_idx = {p: 0 for p in proposers}

    # Precompute receiver preference ranks for quick comparison
    receiver_rank = {r: {p: i for i, p in enumerate(prefs)} for r, prefs in receivers.items()}

    # Current match for receivers: receiver -> proposer
    receiver_match = {}

    # Set of currently free proposers
    free = set(proposers.keys())

    while free:
        p = min(free)  # process free proposers in plain string order
        prefs = proposers[p]

        if next_idx[p] >= len(prefs):
            # No more receivers to propose to (shouldn't happen with equal-size valid input)
            free.remove(p)
            continue

        r = prefs[next_idx[p]]
        next_idx[p] += 1

        if r not in receiver_match:
            receiver_match[r] = p
            free.remove(p)
        else:
            current = receiver_match[r]
            if receiver_rank[r][p] < receiver_rank[r][current]:
                receiver_match[r] = p
                free.remove(p)
                free.add(current)
            # else p stays free, will propose to next receiver on next iteration

    return {p: r for r, p in receiver_match.items()}
